import{z as i,x as C,o as e,c as U,q as t,j as n,D as E,d as B,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const d=JSON.parse('{"title":"CUSUM / MOSUM","description":"","frontmatter":{"title":"CUSUM / MOSUM","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cusum-mosum.md","filePath":"quant/cusum-mosum.md","lastUpdated":1791063341000}'),A={name:"quant/cusum-mosum.md"};function S(l,a,M,h,p,m){const r=C("Mermaid");return e(),U("div",null,[a[2]||(a[2]=t('<h1 id="cusum-mosum" tabindex="-1">CUSUM / MOSUM <a class="header-anchor" href="#cusum-mosum" aria-label="Permalink to &quot;CUSUM / MOSUM&quot;">​</a></h1><div class="epigraph"><p>把递归残差或 OLS 残差依次累加，若回归关系在样本中途换了，累加路径会像带漂移的随机游走一样穿出常数参数下的边界；移动窗口的残差和则对近期断裂更敏感。</p><footer>—— Brown, Durbin and Evans, Techniques for Testing the Constancy of Regression Relationships over Time, JRSS-B, 1975；OLS-CUSUM 见 Ploberger and Krämer, Econometrica, 1992</footer></div><p><a href="/quant/gregory-hansen">Gregory–Hansen</a> 在全样本上搜一个 \\(\\tau\\) 再做残差单位根；<a href="/quant/bai-perron">Bai–Perron</a> 全局切多段。二者都是<strong>事后</strong>、整段样本的检验。CUSUM（累积和）与 MOSUM（移动和）回答另一类问题：沿着时间往前走，参数是否已经不再是历史那一组。Brown、Durbin 与 Evans（1975）用递归残差的累加；Ploberger 与 Krämer（1992）给出 OLS 残差 CUSUM 的渐近；Chu、Hornik 与 Kuan 的 MOSUM 用固定宽度窗口。本篇写递归残差与 OLS 残差的差别、边界怎么来、以及如何把它当成配对与因子模型的<strong>顺序监听</strong>，而不是替代协整检验。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设形成期估好 \\(y=\\hat\\alpha+\\hat\\beta x\\)，交易期继续观测。你想在不知道断裂日期、也不想每个新时点都重跑一遍 inf 型检验的前提下，问：到目前为止的残差，是否还像同一套系数生成的。CUSUM 把标准化残差累加，得到一条路径 \\(W_n(r)\\)；原假设参数恒定、误差条件同方差时，它弱收敛到布朗桥或相关高斯过程，从而有随时间变化的临界带。路径穿带，拒绝恒定。</p><p>与 GH 的差别：CUSUM 的原假设是「回归参数稳定」（常常还默认关系本身存在），不是「无协整」。价差若本来就是 \\(I(1)\\)，残差累加会穿任何带，你得到的是「关系不稳」或「根本没有平稳关系」，分不清。因此 CUSUM 应加在已经通过形成期协整筛选的对上，作为交易期监听；形成期是否存在带断裂的协整，仍用 GH。</p><p><span class="marginnote">术语翻译：CUSUM 就是「把每天的残差记在流水账上持续往上加」。数字实例：若断裂后残差每天平均偏 0.2、标准差为 1，纯噪声下 25 天累加大约停在 ±5 以内（随机游走的量级），而带漂移的累加会走到 \\(0.2\\times25=5\\) 并继续线性向上——「漂移压过扩散」就是穿带的直觉。</span></p><h3 id="递归残差与-ols-残差" tabindex="-1">递归残差与 OLS 残差 <a class="header-anchor" href="#递归残差与-ols-残差" aria-label="Permalink to &quot;递归残差与 OLS 残差&quot;">​</a></h3><p>BDE 的递归残差：用 \\(t-1\\) 及之前的样本估系数，预测 \\(y_t\\)，标准化预测误差。在原假设与正态下，递归残差近似独立 \\(N(0,\\sigma^2)\\)，累加接近随机游走，边界是直线（或斜线）组成的隧道。它对样本<strong>末端</strong>的断裂有势，对样本很早的断裂势弱——早期系数还在学，后期才「看起来稳」。</p><p>OLS-CUSUM 用全样本系数的残差累加，渐近是布朗桥（两端钉在 0）。它对样本中段的水平漂移有势，对只发生在系数斜率上、且回归元均值接近零的变化可能迟钝。MOSUM 把累加换成宽度 \\(h\\) 的移动和，相当于对近期残差重新加权：断裂刚发生时比全历史 CUSUM 更快抬升，但窗口内噪声也更大，虚假穿越更频繁。</p><p><span class="marginnote">「穿线就平仓」把渐近边界当成了滤波器。日频上边界是为检验水平设计的，不是为成本后期望设计的。更干净的做法是：穿越触发降杠杆或冻结开仓，真正的平仓仍用预先写的残差止损与时间止损。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>形成期校准，交易期监听。</strong> 形成期估 \\(\\beta\\) 与残差方差，交易期用递归残差做 CUSUM，边界按预先规定的显著性（常见 5%）画。不要在交易期用含未来的全样本 OLS-CUSUM 来决定「当时该不该停」——那是事后布朗桥，含 \\(\\mathcal{F}_T\\)。可复现的回测只允许用到 \\(t\\) 的递归量。</p><p><strong>MOSUM 的带宽。</strong> \\(h\\) 太短，路径像残差本身，天天穿；太长，退化成缓慢 CUSUM，失去「对近期敏感」的意义。可把 \\(h\\) 设为若干个 <a href="/quant/ou-spread">OU 半衰期</a>，使窗口覆盖一次典型回归，却短于你愿意忍受的破裂时长。同时报告 CUSUM 与 MOSUM：前者稳、后者快，意见不一致时以规则书的优先级为准，而不是看哪条线先动。</p><p><span class="marginnote">数字实例：若价差均值回归的 OU 半衰期约 10 个交易日，取 \\(h=40\\) 天，窗口大约覆盖四次典型回归——正常波动在窗口内能自我抵消，真实的参数破裂则会让整窗残差同号，移动和迅速抬升。若把 \\(h\\) 放大到一年以上，MOSUM 的曲线就长得和 CUSUM 几乎一样，「抓新破裂」的优势消失了。</span></p><p><strong>异方差与肥尾。</strong> 经典边界假定同方差。GARCH 与跳跃会让路径过早穿带。可用残差先除以滚动波动，或用稳健 CUSUM（基于符号或分位数）。金融收益上，未调整的 5% 边界往往过拒；这不意味着「天天都在断裂」，而意味着尺寸被波动聚集破坏。诊断应看：穿越是否伴随滚动 \\(\\beta\\) 的移动，还是只伴随 \\(|u_t|\\) 的一次脉冲。</p><h3 id="顺序监测与样本内检验" tabindex="-1">顺序监测与样本内检验 <a class="header-anchor" href="#顺序监测与样本内检验" aria-label="Permalink to &quot;顺序监测与样本内检验&quot;">​</a></h3><p>Chu、Stinchcombe 与 White 一类顺序监测：从训练样本得到边界，然后在后续流数据上持续检验，控制的是整个监测期的错误警报率，而不是某一个 \\(t\\) 上的点检验。这与「每天重新做一次 Bai–Perron」不同：后者既没有顺序水平，又极贵。工程上，CUSUM/MOSUM 适合日更；BP 适合月末或季末重估 \\(m\\)；GH 适合形成期结束时跑一次。</p><p>对多条腿或因子模型，可对每个系数的递归估计做 CUSUM，或对向量残差做多元 CUSUM。多元版本对相关残差的联合漂移更敏感，但也更容易被一条腿的停牌带动。A 股应在停牌日把该观测标成缺失，递归更新只做预测步，不把零收益当信息。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>参数恒定时，标准化新息均值接近 0，累加是鞅；参数在 \\(\\tau\\) 处跳，之后新息带均值，累加出现线性漂移，终将穿出原假设下的扩散边界。MOSUM 把漂移的检测限制在宽度 \\(h\\) 内，因此对「最近才断」的势高，对「很久以前断、之后新参数已稳定」的势低——很久以前的漂移已经滑出窗口。这解释了分工：MOSUM 抓正在发生的破裂；CUSUM 保留更长记忆；BP 在事后把所有台阶的位置估出来。</p>',21)),(e(),n(s,null,{default:E(()=>[o(r,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20BR%5B%22%E6%96%AD%E8%A3%82%E5%8F%91%E7%94%9F%E5%9C%A8%E4%B8%8D%E5%90%8C%E4%BD%8D%E7%BD%AE%EF%BC%8C%E8%B0%81%E7%9C%8B%E5%BE%97%E8%A7%81%EF%BC%9F%22%5D%20--%3E%20E1%5B%22%E6%A0%B7%E6%9C%AC%E6%97%A9%E6%9C%9F%E6%96%AD%E8%A3%82%22%5D%0A%20%20BR%20--%3E%20E2%5B%22%E6%A0%B7%E6%9C%AC%E4%B8%AD%E6%AE%B5%E6%B0%B4%E5%B9%B3%E6%BC%82%E7%A7%BB%22%5D%0A%20%20BR%20--%3E%20E3%5B%22%E5%88%9A%E5%8F%91%E7%94%9F%E7%9A%84%E6%96%B0%E7%A0%B4%E8%A3%82%22%5D%0A%20%20BR%20--%3E%20E4%5B%22%E5%BE%88%E4%B9%85%E4%BB%A5%E5%89%8D%E6%96%AD%E3%80%81%E6%96%B0%E5%8F%82%E6%95%B0%E5%B7%B2%E7%A8%B3%22%5D%0A%20%20E1%20--%3E%20A1%5B%22%E9%80%92%E5%BD%92%20CUSUM%EF%BC%9A%E5%8A%BF%E5%BC%B1%EF%BC%8C%E7%B3%BB%E6%95%B0%E8%BF%98%E5%9C%A8%E5%AD%A6%22%5D%0A%20%20E2%20--%3E%20A2%5B%22OLS-CUSUM%EF%BC%9A%E5%B8%83%E6%9C%97%E6%A1%A5%EF%BC%8C%E4%B8%AD%E6%AE%B5%E6%9C%80%E6%9C%89%E5%8A%BF%22%5D%0A%20%20E3%20--%3E%20A3%5B%22MOSUM%EF%BC%9A%E7%AA%97%E5%8F%A3%E5%86%85%E6%BC%82%E7%A7%BB%E5%BF%AB%E9%80%9F%E6%8A%AC%E5%8D%87%22%5D%0A%20%20E4%20--%3E%20A4%5B%22MOSUM%20%E5%8A%BF%E4%BD%8E%EF%BC%8CCUSUM%20%E4%BB%8D%E6%9C%89%E8%AE%B0%E5%BF%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与协整的关系：若 \\(\\beta\\) 已错，误差修正项在错误原点上工作，残差均值非零，CUSUM 会漂。若只是 \\(\\sigma\\) 变大而 \\(\\beta\\) 未变，未缩放的 CUSUM 也会更早穿带，你可能把波动体制当成结构断裂。先对残差做波动标准化，再累加，有助于把「方差切换」交给 <a href="/quant/hmm-regime">HMM</a>，把「均值/斜率切换」留给 CUSUM。</p><p><span class="marginnote">常见误区：初学者容易把每次穿带都读成「β 变了」。举例：残差波动从 1% 翻到 2% 而均值仍为零，未缩放的 CUSUM 会在同样累计金额下更快越界，看起来像断裂，其实只是波动放大。先除以滚动波动再累加，才能把这类假警报滤掉。</span></p><p><span class="marginnote">递归残差在 \\(t\\) 用的是 \\(\\hat\\beta_{t-1}\\)，与 <a href="/quant/kalman-hedge">Kalman 对冲</a> 的预测残差同一时点逻辑。回测若误用 \\(\\hat\\beta_t\\)（含当期 \\(y_t\\)）去做 CUSUM，穿越会被推迟或扭曲，看起来更「稳」。</span></p><h3 id="穿越之后做什么" tabindex="-1">穿越之后做什么 <a class="header-anchor" href="#穿越之后做什么" aria-label="Permalink to &quot;穿越之后做什么&quot;">​</a></h3><p>统计拒绝不是最优停时。穿越说明「恒定参数」这条原假设已不可维持，仓位规则应切换到：停止按旧阈值加仓、减杠杆、缩短时间止损、并在足够新样本后重估。重估窗口若从 \\(\\hat\\tau_{\\mathrm{CUSUM}}\\) 才开始，样本短、\\(\\beta\\) 噪；可用衰减加权把旧样本降权而不是清零。若穿越由单一公司行为引起，应先调整价格序列再决定是否重启监听，而不是把除权当成体制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CUSUM 对早段断裂势弱，对晚段强；若你关心形成期内部是否已经被污染，应在形成期结束时跑 GH 或 BP，而不是只看交易期 CUSUM 还没穿。MOSUM 的多重穿越在异方差下会刷屏，必须有冷却期：一次警报之后 \\(h\\) 个观测内不再重复计数，否则操作变成噪声交易。</p><p>不要把 CUSUM 路径当 PnL 图读。不要在未标准化波动时比较不同品种的「谁先穿」。不要用全样本 OLS-CUSUM 的历史穿越点当盘中规则的验证——那是同一条布朗桥的事后 realization。tick 上微观结构会使递归残差高度负相关，经典独立假设失败，应先降频或用核/预平均收益。</p><p><span class="marginnote">边界常数来自布朗运动的穿越概率，和 OU 的开仓倍数没有换算公式。把 5% CUSUM 带当成 2σ 交易阈值，是把检验水平误当成经济阈值。</span></p>',9)),(e(),n(s,null,{default:E(()=>[o(r,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20TD%0A%20%20FORM%5B%22%E5%BD%A2%E6%88%90%E6%9C%9F%E4%BC%B0%20%CE%B2%22%5D%20--%3E%20REC%5B%22%E4%BA%A4%E6%98%93%E6%9C%9F%E9%80%92%E5%BD%92%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20REC%20--%3E%20CS%5B%22CUSUM%20%E7%B4%AF%E7%A7%AF%E5%92%8C%22%5D%0A%20%20REC%20--%3E%20MS%5B%22MOSUM%20%E7%A7%BB%E5%8A%A8%E5%92%8C%22%5D%0A%20%20CS%20--%3E%20BAND%5B%22%E6%B8%90%E8%BF%91%E4%B8%B4%E7%95%8C%E5%B8%A6%22%5D%0A%20%20MS%20--%3E%20BAND%0A%20%20BAND%20--%3E%7C%22%E6%9C%AA%E7%A9%BF%22%7C%20HOLD%5B%22%E7%BB%B4%E6%8C%81%E6%97%A7%E8%A7%84%E5%88%99%22%5D%0A%20%20BAND%20--%3E%7C%22%E7%A9%BF%E8%B6%8A%22%7C%20CUT%5B%22%E5%81%9C%E5%BC%80%E4%BB%93%20%2F%20%E9%99%8D%E6%9D%A0%E6%9D%86%22%5D%0A%20%20CUT%20--%3E%20RE%5B%22%E8%A1%B0%E5%87%8F%E7%AA%97%E5%8F%A3%E9%87%8D%E4%BC%B0%22%5D%0A%20%20FORM%20--%3E%20GH%5B%22%E5%BD%A2%E6%88%90%E6%9C%9F%E6%9C%AB%20GH%20%2F%20BP%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CUSUM / MOSUM 用递归或 OLS 残差的累积和、移动和监听回归参数是否仍恒定，原假设不是「无协整」。</li><li>Brown–Durbin–Evans 递归 CUSUM 对末端断裂更敏感；OLS-CUSUM 渐近为布朗桥；MOSUM 对近期断裂更快但更噪。</li><li>顺序监测控制的是整段监测期的错误警报率；适合做交易期过滤器，形成期协整仍用 Gregory–Hansen。</li><li>异方差会使未缩放边界过拒；穿越后应降杠杆并重估，而不是把穿线当开平信号。</li><li>与 Bai–Perron、HMM 分工：监听、事后切段、反复体制，三者不要用同一条临界值。</li><li>出处：Brown, Durbin and Evans, <em>JRSS-B</em>, 1975；Ploberger and Krämer, <em>Econometrica</em>, 1992；Chu, Hornik and Kuan 的 MOSUM；顺序监测见 Chu, Stinchcombe and White。</li></ul>',2))])}const D=i(A,[["render",S]]);export{d as __pageData,D as default};
